import { useEffect, useState } from "react";
import { Route, Routes, useNavigate } from "react-router-dom";
import HomePage from "./Pages/HomePage/HomePage";
import Dashboard from "./Pages/Dashboard/Dashboard";
import axios from "axios";

import "./App.css";
import "./Responsive.css";

function App() {
  const navigate = useNavigate();
  const [password, setPassword] = useState("");
  const [isAuthorized, setIsAuthorized] = useState(localStorage.getItem("isAuthorized") === "true");
  const [activeSection, setActiveSection] = useState("EditHomePage");
  const [getLogos, setGetLogos] = useState([]);

  useEffect(() => {
    const fetchImages = async () => {
      try {
        const response = await axios.get("http://localhost:5000/images");
        setGetLogos(response.data?.[0].Logos?.filter((ele) => ele.isActive === true)?.[0] || []);
      } catch (error) {
        console.error("Error fetching images:", error);
      }
    };
    fetchImages();
  }, []);

  const verifyPasswordContent = async () => {
    try {
      const response = await axios.post("http://localhost:5000/verify-password", {
        password: password,
      });
      if (response.data.status === true) {
        localStorage.setItem("isAuthorized", "true");
        setIsAuthorized(true);
        navigate("/Dashboard");
      }
    } catch (error) {
      console.error("❌ Password verification failed:", error.response?.data || error.message);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("isAuthorized");
    setIsAuthorized(false);
    navigate("/");
  };

  return (
    <div className="App">
      {!isAuthorized ? (
        <div className="password-form">
          <h2>Password Required</h2>
          <input
            type="password"
            placeholder="Enter password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <button
            style={{ width: "113px", height: "40px", padding: "4px 8px", margin: "6px" }}
            onClick={verifyPasswordContent}
          >
            Submit
          </button>
        </div>
      ) : (
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route
            path="/Dashboard"
            element={
              <Dashboard
                getLogos={getLogos}
                activeSection={activeSection}
                setActiveSection={setActiveSection}
                handleLogout={handleLogout}
              />
            }
          />
        </Routes>
      )}
    </div>
  );
}

export default App;
